  // Detect intents in user input for the AI dock
  function detectIntent(text, lang) {
    const t = (text || '').toLowerCase();
    if (/(service|expert|fait|do|offer|métier|crafts?|pôles?|pillar)/.test(t)) return 'services';
    if (/(ia|ai|intelligence|chatbot|automatis|automat|workflow|machine|ml|data)/.test(t)) return 'ai';
    if (/(prix|tarif|cout|coût|cost|price|budget|combien|how much|quote|devis)/.test(t)) return 'price';
    if (/(contact|joindre|email|mail|téléphone|telephone|phone|appeler|reach|talk|whatsapp|adresse|address)/.test(t)) return 'contact';
    return 'default';
  }

